diff -ruN '--exclude=node_modules' '--exclude=.git' a/csv-stream.test.ts b/csv-stream.test.ts
--- a/csv-stream.test.ts	1970-01-01 00:00:00.000000000 +0000
+++ b/csv-stream.test.ts	2026-10-29 17:15:46.760370691 +0000
@@ -0,0 +1,67 @@
+import { expect, test } from "bun:test";
+import { CsvStream, parseCsv } from "./csv";
+
+function streamAll(parts: string[]): string[][] {
+  const s = new CsvStream();
+  return [...parts.flatMap((p) => s.push(p)), ...s.end()];
+}
+
+test("stream equals parseCsv for every split into three chunks", () => {
+  const inputs = ["", "\uFEFF", "\uFEFFa", "a\r\nb\r", "a\r", "\r\n", "a,\n,\n\n", '"a""b",\r\n"c\r\nd"', '"a"', 'a,"b"\r\n', "a\rb,c\r\r\n", "x\n"];
+  for (const t of inputs)
+    for (let i = 0; i <= t.length; i++)
+      for (let j = i; j <= t.length; j++) expect(streamAll([t.slice(0, i), t.slice(i, j), t.slice(j)])).toEqual(parseCsv(t));
+});
+
+test("random inputs agree with parseCsv, rows or SyntaxError", () => {
+  let seed = 12345;
+  const rnd = (n: number) => ((seed = (seed * 1103515245 + 12345) & 0x7fffffff), seed % n);
+  const alphabet = ["a", ",", '"', "\r", "\n", "\uFEFF"];
+  for (let k = 0; k < 2000; k++) {
+    let t = "";
+    for (let n = rnd(13); n > 0; n--) t += alphabet[rnd(alphabet.length)];
+    let expected: string[][] | "error";
+    try {
+      expected = parseCsv(t);
+    } catch {
+      expected = "error";
+    }
+    for (let i = 0; i <= t.length; i++) {
+      const parts = [t.slice(0, i), t.slice(i)];
+      if (expected === "error") expect(() => streamAll(parts)).toThrow(SyntaxError);
+      else expect(streamAll(parts)).toEqual(expected);
+    }
+  }
+});
+
+test("a row is returned once its row end arrives, a lone \\r stays in the field", () => {
+  const s = new CsvStream();
+  expect(s.push("a\r")).toEqual([]);
+  expect(s.push("\nb\r")).toEqual([["a"]]);
+  expect(s.push("c")).toEqual([]);
+  expect(s.end()).toEqual([["b\rc"]]);
+});
+
+test("errors are thrown at the push or end that shows them, and stay", () => {
+  const s = new CsvStream();
+  s.push('"a"');
+  expect(() => s.push("b")).toThrow(SyntaxError);
+  expect(() => s.end()).toThrow(SyntaxError);
+  const t = new CsvStream();
+  t.push('"ab');
+  expect(() => t.end()).toThrow(SyntaxError);
+});
+
+test("the BOM is dropped only at the very start", () => {
+  expect(streamAll(["", "\uFEFFa"])).toEqual([["a"]]);
+  expect(streamAll(["a", "\uFEFF"])).toEqual([["a\uFEFF"]]);
+});
+
+test("one-character chunks over a large input stay linear", () => {
+  const s = new CsvStream();
+  let n = 0;
+  for (const c of '"' + "x".repeat(200000) + '"\n') n += s.push(c).length;
+  for (let r = 0; r < 20000; r++) for (const c of "x,y\n") n += s.push(c).length;
+  expect(n).toBe(20001);
+  expect(s.end()).toEqual([]);
+});
diff -ruN '--exclude=node_modules' '--exclude=.git' a/csv.ts b/csv.ts
--- a/csv.ts	2026-10-29 17:14:42.018431996 +0000
+++ b/csv.ts	2026-10-29 17:15:46.755223384 +0000
@@ -50,3 +50,117 @@
   rows.push(row);
   return rows;
 }
+
+type CsvState = "start" | "plain" | "plainCr" | "quoted" | "quote" | "quoteCr";
+
+/** Incremental `parseCsv`: the rows of all `push` and `end` results together equal `parseCsv` of the whole input. */
+export class CsvStream {
+  private state: CsvState = "start";
+  private rows: string[][] = [];
+  private row: string[] = [];
+  private field = "";
+  private fresh = true; // nothing read since the last row end
+  private first = true; // no character read yet
+  private failure: SyntaxError | undefined;
+
+  push(chunk: string): string[][] {
+    if (this.failure) throw this.failure;
+    try {
+      for (let i = 0; i < chunk.length; i++) {
+        const c = chunk[i]!;
+        if (this.first) {
+          this.first = false;
+          if (c === "\uFEFF") continue;
+        }
+        this.step(c);
+      }
+    } catch (e) {
+      this.failure = e as SyntaxError;
+      throw e;
+    }
+    const out = this.rows;
+    this.rows = [];
+    return out;
+  }
+
+  end(): string[][] {
+    if (this.failure) throw this.failure;
+    let fail: string | undefined;
+    if (this.state === "quoted") fail = "a quoted field is still open at the end of the input";
+    else if (this.state === "quoteCr") fail = 'unexpected "\\r" after a closing quote';
+    if (fail) {
+      this.failure = new SyntaxError(fail);
+      throw this.failure;
+    }
+    if (this.state === "plainCr") this.field += "\r";
+    if (!this.fresh) this.endRow();
+    this.state = "start";
+    this.fresh = true;
+    const out = this.rows;
+    this.rows = [];
+    return out;
+  }
+
+  private endField() {
+    this.row.push(this.field);
+    this.field = "";
+  }
+
+  private endRow() {
+    this.endField();
+    this.rows.push(this.row);
+    this.row = [];
+    this.state = "start";
+    this.fresh = true;
+  }
+
+  private step(c: string) {
+    this.fresh = false;
+    switch (this.state) {
+      case "start":
+        if (c === '"') this.state = "quoted";
+        else this.plain(c);
+        return;
+      case "plain":
+        this.plain(c);
+        return;
+      case "plainCr":
+        if (c === "\n") return this.endRow();
+        this.field += "\r";
+        this.state = "plain";
+        this.plain(c);
+        return;
+      case "quoted":
+        if (c === '"') this.state = "quote";
+        else this.field += c;
+        return;
+      case "quote":
+        if (c === '"') {
+          this.field += '"';
+          this.state = "quoted";
+        } else if (c === ",") {
+          this.endField();
+          this.state = "start";
+        } else if (c === "\n") this.endRow();
+        else if (c === "\r") this.state = "quoteCr";
+        else throw new SyntaxError(`unexpected ${JSON.stringify(c)} after a closing quote`);
+        return;
+      case "quoteCr":
+        if (c === "\n") return this.endRow();
+        throw new SyntaxError('unexpected "\\r" after a closing quote');
+    }
+  }
+
+  private plain(c: string) {
+    if (c === ",") {
+      this.endField();
+      this.state = "start";
+    } else if (c === "\n") this.endRow();
+    else if (c === "\r") this.state = "plainCr";
+    else if (c === '"') throw new SyntaxError("a quote in a field that is not quoted");
+    else {
+      this.field += c;
+      this.state = "plain";
+    }
+  }
+}

diff -ruN '--exclude=node_modules' '--exclude=.git' a/csv.stream.test.ts b/csv.stream.test.ts
--- a/csv.stream.test.ts	1970-01-01 00:00:00.000000000 +0000
+++ b/csv.stream.test.ts	2026-10-29 17:16:47.264835062 +0000
@@ -0,0 +1,108 @@
+import { expect, test } from "bun:test";
+import { CsvStream, parseCsv } from "./csv";
+
+function run(s: string, cuts: number[]): string[][] {
+  const st = new CsvStream();
+  const out: string[][] = [];
+  let p = 0;
+  for (const c of [...cuts, s.length]) {
+    out.push(...st.push(s.slice(p, c)));
+    p = c;
+  }
+  out.push(...st.end());
+  return out;
+}
+
+function agree(s: string, cuts: number[]) {
+  let expected: string[][] | Error;
+  try {
+    expected = parseCsv(s);
+  } catch (e) {
+    expected = e as Error;
+  }
+  if (expected instanceof Error) {
+    expect(() => run(s, cuts)).toThrow(SyntaxError);
+    try {
+      run(s, cuts);
+    } catch (e) {
+      expect((e as Error).message).toBe(expected.message);
+    }
+  } else expect(run(s, cuts)).toEqual(expected);
+}
+
+test("a pending \\r, a quote at a chunk end and a quote doubled across chunks", () => {
+  const s = new CsvStream();
+  expect(s.push("a,b\r")).toEqual([]);
+  expect(s.push("\nc\r")).toEqual([["a", "b"]]);
+  expect(s.push('d,"x"')).toEqual([]);
+  expect(s.push('"y')).toEqual([]);
+  expect(s.push('"\r')).toEqual([]);
+  expect(s.push("\n")).toEqual([["c\rd", 'x"y']]);
+  expect(s.end()).toEqual([]);
+});
+
+test("errors arrive with the chunk that shows them", () => {
+  const a = new CsvStream();
+  expect(a.push('"a"')).toEqual([]);
+  expect(() => a.push("b")).toThrow(SyntaxError);
+  const b = new CsvStream();
+  b.push('"a"\r');
+  expect(() => b.push("x")).toThrow(SyntaxError);
+  const c = new CsvStream();
+  c.push('"ab');
+  expect(() => c.end()).toThrow(SyntaxError);
+  const d = new CsvStream();
+  d.push('"a"\r');
+  expect(() => d.end()).toThrow(SyntaxError);
+});
+
+test("the BOM is dropped only at the very start", () => {
+  const s = new CsvStream();
+  s.push("");
+  expect(s.push("\ufeffa\n")).toEqual([["a"]]);
+  expect(run("a\ufeff", [1])).toEqual([["a\ufeff"]]);
+  expect(run("\ufeff", [])).toEqual([]);
+});
+
+test("every split of every short input matches parseCsv", () => {
+  const alphabet = ["a", ",", '"', "\r", "\n", "\ufeff"];
+  const gen = (s: string, n: number) => {
+    if (n === 0) {
+      for (let mask = 0; mask < 1 << Math.max(0, s.length - 1); mask++) {
+        const cuts = [];
+        for (let k = 1; k < s.length; k++) if (mask & (1 << (k - 1))) cuts.push(k);
+        agree(s, cuts);
+      }
+      return;
+    }
+    for (const a of alphabet) gen(s + a, n - 1);
+  };
+  for (let n = 0; n <= 5; n++) gen("", n);
+});
+
+test("work per chunk does not grow with earlier input", () => {
+  const s = new CsvStream();
+  s.push('"');
+  for (let i = 0; i < 300000; i++) s.push("x");
+  expect(s.push('"\n')).toHaveLength(1);
+  let n = 0;
+  for (let i = 0; i < 100000; i++) n += s.push("a,b\n").length;
+  expect(n).toBe(100000);
+});
+
+test("after a SyntaxError every later call throws it again", () => {
+  const s = new CsvStream();
+  let first: unknown;
+  try {
+    s.push('"a"b');
+  } catch (e) {
+    first = e;
+  }
+  expect(first).toBeInstanceOf(SyntaxError);
+  expect(() => s.push("\nx\n")).toThrow(first as Error);
+  expect(() => s.end()).toThrow(first as Error);
+  const t = new CsvStream();
+  t.push('"ab');
+  expect(() => t.end()).toThrow(SyntaxError);
+  expect(() => t.end()).toThrow(SyntaxError);
+});
diff -ruN '--exclude=node_modules' '--exclude=.git' a/csv.ts b/csv.ts
--- a/csv.ts	2026-10-29 17:14:42.027450847 +0000
+++ b/csv.ts	2026-10-29 17:16:47.264362189 +0000
@@ -50,3 +50,115 @@
   rows.push(row);
   return rows;
 }
+
+/** Incremental `parseCsv`: feed chunks to `push`, call `end` once the input is over. */
+export class CsvStream {
+  // 0 field start, 1 unquoted, 2 quoted, 3 quote seen inside quoted, 4 after the closing quote
+  private mode = 0;
+  private cr = false; // a `\r` is waiting for the next char to say whether it ends the row
+  private first = true;
+  private rowStart = true;
+  private field = "";
+  private row: string[] = [];
+  private offset = 0;
+  private failed: SyntaxError | undefined;
+
+  push(chunk: string): string[][] {
+    return this.guard(() => this.pushChunk(chunk));
+  }
+
+  end(): string[][] {
+    return this.guard(() => this.finish());
+  }
+
+  /** After a SyntaxError every later call throws it again, so a rejected input never yields more rows. */
+  private guard(run: () => string[][]): string[][] {
+    if (this.failed) throw this.failed;
+    try {
+      return run();
+    } catch (e) {
+      if (e instanceof SyntaxError) this.failed = e;
+      throw e;
+    }
+  }
+
+  private pushChunk(chunk: string): string[][] {
+    const rows: string[][] = [];
+    for (let k = 0; k < chunk.length; k++) {
+      const c = chunk[k]!;
+      this.offset++;
+      if (this.first) {
+        this.first = false;
+        if (c === "\ufeff") continue;
+      }
+      this.rowStart = false;
+      this.step(c, rows);
+    }
+    return rows;
+  }
+
+  private finish(): string[][] {
+    const rows: string[][] = [];
+    if (this.rowStart) return rows;
+    if (this.mode === 2) throw new SyntaxError("a quoted field is still open at the end of the input");
+    if (this.cr) {
+      if (this.mode === 4) throw new SyntaxError(`unexpected "\\r" after a closing quote at offset ${this.offset - 1}`);
+      this.field += "\r";
+      this.cr = false;
+    }
+    this.row.push(this.field);
+    rows.push(this.row);
+    this.field = "";
+    this.row = [];
+    this.mode = 0;
+    this.rowStart = true;
+    return rows;
+  }
+
+  private endField() {
+    this.row.push(this.field);
+    this.field = "";
+    this.mode = 0;
+  }
+
+  private endRow(rows: string[][]) {
+    this.endField();
+    rows.push(this.row);
+    this.row = [];
+    this.rowStart = true;
+  }
+
+  private step(c: string, rows: string[][]) {
+    if (this.cr) {
+      this.cr = false;
+      if (c === "\n") return this.endRow(rows);
+      if (this.mode === 4) throw new SyntaxError(`unexpected "\\r" after a closing quote at offset ${this.offset - 2}`);
+      this.field += "\r";
+    }
+    if (this.mode === 3) {
+      if (c === '"') {
+        this.field += '"';
+        this.mode = 2;
+        return;
+      }
+      this.mode = 4;
+    } else if (this.mode === 2) {
+      if (c === '"') this.mode = 3;
+      else this.field += c;
+      return;
+    } else if (this.mode === 0) {
+      if (c === '"') {
+        this.mode = 2;
+        return;
+      }
+      this.mode = 1;
+    }
+    // mode 1 or 4
+    if (c === ",") this.endField();
+    else if (c === "\n") this.endRow(rows);
+    else if (c === "\r") this.cr = true;
+    else if (this.mode === 4) throw new SyntaxError(`unexpected ${JSON.stringify(c)} after a closing quote at offset ${this.offset - 1}`);
+    else if (c === '"') throw new SyntaxError(`a quote in a field that is not quoted, at offset ${this.offset - 1}`);
+    else this.field += c;
+  }
+}

diff -ruN '--exclude=node_modules' '--exclude=.git' a/csv-stream.test.ts b/csv-stream.test.ts
--- a/csv-stream.test.ts	1970-01-01 00:00:00.000000000 +0000
+++ b/csv-stream.test.ts	2026-10-29 17:17:40.219662833 +0000
@@ -0,0 +1,68 @@
+import { expect, test } from "bun:test";
+import { CsvStream, parseCsv } from "./csv";
+
+function streamAll(parts: string[]): string[][] {
+  const s = new CsvStream();
+  const out: string[][] = [];
+  for (const p of parts) out.push(...s.push(p));
+  out.push(...s.end());
+  return out;
+}
+
+test("any split of any short input matches parseCsv, errors included", () => {
+  const alphabet = ['"', ",", "\r", "\n", "a", "\ufeff"];
+  const inputs: string[] = [""];
+  for (let len = 1; len <= 7; len++) {
+    const n = alphabet.length ** len;
+    for (let k = 0; k < n; k += len > 6 ? 3 : 1) {
+      let s = "";
+      for (let j = 0, x = k; j < len; j++, x = Math.floor(x / alphabet.length)) s += alphabet[x % alphabet.length];
+      inputs.push(s);
+    }
+  }
+  for (const input of inputs) {
+    let expected: string[][] | "err";
+    try {
+      expected = parseCsv(input);
+    } catch {
+      expected = "err";
+    }
+    for (const cut of [input.length || 1, 1, 2, 3]) {
+      const parts: string[] = [];
+      for (let p = 0; p < input.length; p += cut) parts.push(input.slice(p, p + cut));
+      if (expected === "err") expect(() => streamAll(parts)).toThrow(SyntaxError);
+      else expect(streamAll(parts)).toEqual(expected);
+    }
+  }
+});
+
+test("a BOM alone or after an empty chunk is dropped; a split \\r\\n is one row end", () => {
+  expect(streamAll(["", "\ufeff", "a\r", "\nb"])).toEqual([["a"], ["b"]]);
+  expect(streamAll(["\ufeff"])).toEqual([]);
+  expect(streamAll(["a\n\ufeffb"])).toEqual([["a"], ["\ufeffb"]]);
+});
+
+test("a row is returned as soon as its row end arrives", () => {
+  const s = new CsvStream();
+  expect(s.push("a\r")).toEqual([]);
+  expect(s.push("\n")).toEqual([["a"]]);
+  expect(s.push('"b"')).toEqual([]);
+  expect(s.push("\r")).toEqual([]);
+  expect(s.push("\n")).toEqual([["b"]]);
+});
+
+test("errors surface and stick", () => {
+  const s = new CsvStream();
+  s.push('"abc');
+  expect(() => s.end()).toThrow(SyntaxError);
+  expect(() => s.push("x")).toThrow(SyntaxError);
+  expect(() => streamAll(['"a"', "b"])).toThrow(SyntaxError);
+  expect(() => streamAll(['"a"\r', "b"])).toThrow(SyntaxError);
+});
+
+test("long inputs in one-char chunks match parseCsv", () => {
+  const big = '"' + "x,\n".repeat(60000) + '"';
+  expect(streamAll([...big])).toEqual(parseCsv(big));
+  const rows = "ab,c\r\n".repeat(20000);
+  expect(streamAll([...rows])).toEqual(parseCsv(rows));
+});
diff -ruN '--exclude=node_modules' '--exclude=.git' a/csv.ts b/csv.ts
--- a/csv.ts	2026-10-29 17:16:42.321583084 +0000
+++ b/csv.ts	2026-10-29 17:17:40.215230129 +0000
@@ -50,3 +50,123 @@
   rows.push(row);
   return rows;
 }
+
+/**
+ * Incremental `parseCsv`: feed chunks of any size to `push`, then call `end`. Rows come back once their row end has
+ * arrived; only the open row and field are held. After a SyntaxError every later call throws it again.
+ */
+export class CsvStream {
+  private rows: string[][] = [];
+  private row: string[] = [];
+  private field = "";
+  // start: nothing of the field seen; plain: inside an unquoted field; quoted: inside quotes;
+  // quote: a `"` inside quotes that closes the field or starts `""`; after: a quoted field has closed
+  private state: "start" | "plain" | "quoted" | "quote" | "after" = "start";
+  private cr = false; // a `\r` was seen that is a row end only if `\n` follows
+  private any = false; // the current row has consumed input
+  private bomChecked = false;
+  private failed: SyntaxError | undefined;
+
+  push(chunk: string): string[][] {
+    return this.guard(() => this.consume(chunk));
+  }
+
+  end(): string[][] {
+    return this.guard(() => this.finish());
+  }
+
+  private guard(run: () => string[][]): string[][] {
+    if (this.failed) throw this.failed;
+    try {
+      return run();
+    } catch (e) {
+      if (e instanceof SyntaxError) this.failed = e;
+      throw e;
+    }
+  }
+
+  private take(): string[][] {
+    const out = this.rows;
+    this.rows = [];
+    return out;
+  }
+
+  private consume(chunk: string): string[][] {
+    let i = 0;
+    if (!this.bomChecked && chunk.length > 0) {
+      this.bomChecked = true;
+      if (chunk[0] === "\ufeff") i = 1;
+    }
+    for (; i < chunk.length; i++) {
+      const c = chunk[i]!;
+      this.any = true;
+      if (this.state === "quoted") {
+        if (c === '"') this.state = "quote";
+        else this.field += c;
+        continue;
+      }
+      if (this.state === "quote") {
+        if (c === '"') {
+          this.field += '"';
+          this.state = "quoted";
+          continue;
+        }
+        this.state = "after";
+      }
+      if (this.cr) {
+        if (c === "\n") {
+          this.endRow();
+          continue;
+        }
+        if (this.state === "after") throw new SyntaxError(`unexpected "\\r" after a closing quote`);
+        this.field += "\r";
+        this.cr = false;
+      }
+      if (this.state === "start" && c === '"') this.state = "quoted";
+      else if (c === ",") this.endField();
+      else if (c === "\n") this.endRow();
+      else if (c === "\r") {
+        this.cr = true;
+        if (this.state === "start") this.state = "plain";
+      } else if (this.state === "after") throw new SyntaxError(`unexpected ${JSON.stringify(c)} after a closing quote`);
+      else if (c === '"') throw new SyntaxError("a quote in a field that is not quoted");
+      else {
+        this.field += c;
+        this.state = "plain";
+      }
+    }
+    return this.take();
+  }
+
+  private finish(): string[][] {
+    if (this.state === "quoted") throw new SyntaxError("a quoted field is still open at the end of the input");
+    if (this.any) {
+      if (this.cr) {
+        if (this.state === "after" || this.state === "quote") throw new SyntaxError(`unexpected "\\r" after a closing quote`);
+        this.field += "\r";
+        this.cr = false;
+      }
+      this.row.push(this.field);
+      this.rows.push(this.row);
+      this.row = [];
+      this.field = "";
+      this.any = false;
+      this.state = "start";
+    }
+    return this.take();
+  }
+
+  private endField() {
+    this.row.push(this.field);
+    this.field = "";
+    this.state = "start";
+  }
+
+  private endRow() {
+    this.endField();
+    this.rows.push(this.row);
+    this.row = [];
+    this.any = false;
+    this.cr = false;
+  }
+}

